<?php
namespace Wortek\Store\Controllers;
use Wortek\Store\Http\Response; use Wortek\Store\Repositories\PurchaseRepository; use Wortek\Store\Repositories\StockRepository;
final class PurchaseController { public function __construct(private PurchaseRepository $r,private StockRepository $stock){} public function index(): never{Response::success(['compras'=>$this->r->all()]);} public function show(int $id): never{$x=$this->r->find($id);if(!$x)Response::error('Compra não encontrada.',404);Response::success(['compra'=>$x]);} public function store(int $uid): never{$d=json_decode(file_get_contents('php://input'),true);if(!is_array($d)||empty($d['fornecedor_id'])||empty($d['itens']))Response::error('Fornecedor e itens são obrigatórios.',422);$id=$this->r->create($d,$d['itens'],$uid);Response::success(['message'=>'Compra criada.','compra'=>$this->r->find($id)],201);} public function receive(int $id,int $uid): never{$x=$this->r->find($id);if(!$x)Response::error('Compra não encontrada.',404);if($x['estado']==='recebida')Response::error('Compra já recebida.',422);foreach($x['itens'] as $it)$this->stock->move((int)$it['produto_id'],'entrada',(float)$it['quantidade'],'Recepção da compra '.$x['numero'],$uid,'compra',$id);$this->r->updateStatus($id,'recebida');Response::success(['message'=>'Compra recebida e stock actualizado.','compra'=>$this->r->find($id)]);} }
